  setSelection(ids: string[]): void {
    const wanted = new Set(ids);
    for (const [id, entry] of this.objEntries) {
      entry.el.classList.toggle('pc-selected', wanted.has(id));
    }
  }

  /** Current object id→element map (stable DOM identity, tests/hit-testing). */
  get objectElements(): ReadonlyMap<string, SVGGElement> {
    return this.objEntries;
