{"new_string":"/** Nearest link within slop px of the point (perpendicular hit), or null. */
export function hitLink(
  links: SceneLink[],
  p: { x: number; y: number },
  slop = LINK_HIT_SLOP_PX,
): SceneLink | null {
  let best: SceneLink | null = null;
  let bestDist = Infinity;
  for (let i = links.length - 1; i >= 0; i--) {
    const l = links[i];
    if (!l) continue;
    const d = distanceToPolyline(p, l.points as Polyline);
    if (d <= slop && d < bestDist) {
      bestDist = d;
      best = l;
    }
  }
  return best;
}","old_string":"/** Nearest link within slop px of the point (perpendicular hit), or null. */
