{"content":"// SPDX-License-Identifier: GPL-3.0-only
// Canvas controller (M2-WP1/4/6 wiring): owns diagram state + viewport,
// translates pointer/wheel/keyboard input into mode state machines, commits
// mutations through the undo stack (FR-C1/C2/C4/C7/C9). DOM writes go to the
// SceneRenderer only; App reads snapshots via onState.

import {
  SceneRenderer,
  type Scene,
  type SceneLink,
} from '../engine/render/scenegraph';
import { routeOrtho, portPoint, type Side, type Polyline } from '../engine/render/router';
import {
  apply,
  invert,
  panBy,
  zoomAt,
  fitRect,
  unionRects,
  wheelGesture,
  actionFor,
  PAN_STEP_PX,
  ZOOM_STEP,
  type Point,
  type Rect,
  type Transform,
} from '../engine/render/viewport';
import { snapToGrid, computeGuides, snapResize, GRID_SIZE } from '../engine/render/snap';
import { pick } from '../engine/render/hit-test';
import {
  clearOverlay,
  drawRubberBand,
  drawGuides,
  drawGhostLink,
  drawHalos,
  drawResizeHandle,
  type HaloSide,
} from '../engine/render/overlay';
import { ValueChange, UndoStack, type CoalescableCommand } from '../workspace/undo';
import type { Kind } from '../engine/model/types';

export interface DiagramObject {
  id: string;
  kind: Kind;
  x: number;
  y: number;
  w: number;
  h: number;
  name?: string;
  description?: string;
  technology?: string;
  tags?: string[];
  dashed?: boolean;
}

export interface DiagramLink {
  id: string;
  from: string;
  to: string;
  type: string;
  label?: string;
  dashed?: boolean;
}

export interface DiagramState {
  objects: DiagramObject[];
  links: DiagramLink[];
}

export const DEFAULT_SHAPE: Record<Kind, { w: number; h: number }> = {
  person: { w: 120, h: 72 },
  system: { w: 160, h: 60 },
  system_ext: { w: 160, h: 60 },
  container: { w: 160, h: 60 },
  component: { w: 160, h: 60 },
  datastore: { w: 140, h: 64 },
  queue: { w: 140, h: 60 },
  group: { w: 320, h: 240 },
  note: { w: 160, h: 88 },
};

const PALETTE_ORDER: Kind[] = [
  'person',
  'system',
  'system_ext',
  'container',
  'component',
  'datastore',
  'queue',
  'group',
  'note',
];

const RESIZE_KINDS: ReadonlySet<Kind> = new Set(['group']);

type Mode =
  | { t: 'idle' }
  | { t: 'pan'; startScreen: Point; startT: Transform }
  | { t: 'drag'; startCanvas: Point; before: PositionRec[]; moved: boolean }
  | { t: 'band'; startCanvas: Point; additive: boolean }
  | { t: 'link'; fromId: string; fromSide: Side }
  | { t: 'resize'; id: string; startCanvas: Point; before: Rect };

interface PositionRec {
  id: string;
  x: number;
  y: number;
}

export interface ControllerOptions {
  undo?: UndoStack;
  onState?: (s: Snapshot) => void;
  onRenameRequest?: (id: string) => void;
}

export interface Snapshot {
  objects: DiagramObject[];
  links: DiagramLink[];
  selection: { objects: string[]; links: string[] };
  viewport: Transform;
}

export class CanvasController {
  readonly undo: UndoStack;
  private readonly svg: SVGSVGElement;
  private readonly renderer: SceneRenderer;
  private state: DiagramState = { objects: [], links: [] };
  private t: Transform = { x: 0, y: 0, k: 1 };
  private mode: Mode = { t: 'idle' };
  private selObjects = new Set<string>();
  private selLinks = new Set<string>();
  private gridOn = false;
  private spaceDown = false;
  private routes = new Map<string, Polyline>();
  private seq = 0;
  private readonly onState?: (s: Snapshot) => void;
  private readonly onRenameRequest?: (id: string) => void;
  private detach: Array<() => void> = [];

  constructor(svg: SVGSVGElement, opts: ControllerOptions = {}) {
    this.svg = svg;
    this.undo = opts.undo ?? new UndoStack();
    this.onState = opts.onState;
    this.onRenameRequest = opts.onRenameRequest;
    this.renderer = new SceneRenderer(svg);
    this.attach();
    this.render();
  }

  destroy(): void {
    for (const d of this.detach) d();
    this.detach = [];
  }

  // ---- public API (App/palette/properties) --------------------------------

  get viewport(): Transform {
    return this.t;
  }

  get snapshot(): Snapshot {
    return {
      objects: this.state.objects,
      links: this.state.links,
      selection: { objects: [...this.selObjects], links: [...this.selLinks] },
      viewport: this.t,
    };
  }

  selectedObject(): DiagramObject | null {
    if (this.selObjects.size !== 1) return null;
    const id = [...this.selObjects][0];
    return this.state.objects.find((o) => o.id === id) ?? null;
  }

  selectedLink(): DiagramLink | null {
    if (this.selLinks.size !== 1) return null;
    const id = [...this.selLinks][0];
    return this.state.links.find((l) => l.id === id) ?? null;
  }

  /** Place a new object (palette click-to-place / drag-drop / 1..9). */
  addObject(kind: Kind, at?: Point): string {
    const size = DEFAULT_SHAPE[kind];
    const p = at ?? this.centerOfView();
    const x = at ? p.x - size.w / 2 : snapToGrid(p.x - size.w / 2);
    const y = at ? p.y - size.h / 2 : snapToGrid(p.y - size.h / 2);
    const id = `o${++this.seq}`;
    const obj: DiagramObject = {
      id,
      kind,
      x,
      y,
      w: size.w,
      h: size.h,
      name: `${labelFor(kind)} ${this.seq}`,
    };
    this.state = { ...this.state, objects: [...this.state.objects, obj] };
    this.selectObjects([id]);
    const before = this.state.objects.filter((o) => o.id !== id);
    this.undo.push(makeAddCommand(obj, before, this, () => this.state.links));
    this.render();
    return id;
  }

  /** Quick-add by palette index 1..9 (FR-C3). */
  quickAdd(index1to9: number): string | null {
    const kind = PALETTE_ORDER[index1to9 - 1];
    return kind ? this.addObject(kind) : null;
  }

  /** Patch editable fields of an object (properties panel, FR-C6). */
  updateObject(id: string, patch: Partial<Pick<DiagramObject, 'name' | 'description' | 'technology' | 'tags' | 'dashed'>>): void {
    const obj = this.state.objects.find((o) => o.id === id);
    if (!obj) return;
    const before = this.state.objects;
    const after = before.map((o) => (o.id === id ? { ...o, ...patch } : o));
    this.state = { ...this.state, objects: after };
    const set = (objects: DiagramObject[]) => {
      this.state = { ...this.state, objects };
      this.render();
    };
    this.undo.push(
      new ValueChange<DiagramObject[]>(set, before, after, `props:${id}`, 'edit properties', listEq),
    );
    this.render();
  }

  /** Patch a link (type/label/dashed, FR-C7). */
  updateLink(id: string, patch: Partial<Pick<DiagramLink, 'type' | 'label' | 'dashed'>>): void {
    const link = this.state.links.find((l) => l.id === id);
    if (!link) return;
    const before = this.state.links;
    const after = before.map((l) => (l.id === id ? { ...l, ...patch } : l));
    this.state = { ...this.state, links: after };
    const set = (links: DiagramLink[]) => {
      this.state = { ...this.state, links };
      this.recomputeRoutes();
      this.render();
    };
    this.undo.push(
      new ValueChange<DiagramLink[]>(set, before, after, `link:${id}`, 'edit link', listEq),
    );
    this.recomputeRoutes();
    this.render();
  }

  deleteSelection(): void {
    if (this.selObjects.size === 0 && this.selLinks.size === 0) return;
    const beforeObjects = this.state.objects;
    const beforeLinks = this.state.links;
    const removedIds = new Set(this.selObjects);
    const afterObjects = beforeObjects.filter((o) => !removedIds.has(o.id));
    const afterLinks = beforeLinks.filter(
      (l) => !removedIds.has(l.from) && !removedIds.has(l.to) && !this.selLinks.has(l.id),
    );
    this.state = { objects: afterObjects, links: afterLinks };
    this.selectObjects([]);
    this.selLinks.clear();
    this.undo.push(makeDeleteCommand(beforeObjects, beforeLinks, afterObjects, afterLinks, this));
    this.render();
  }

  setSelection(objects: string[], links: string[] = []): void {
    this.selObjects = new Set(objects);
    this.selLinks = new Set(links);
    this.render();
  }

  toggleGrid(): boolean {
    this.gridOn = !this.gridOn;
    this.renderer.setGrid(this.gridOn);
    return this.gridOn;
  }

  fitDiagram(): void {
    const u = unionRects(this.state.objects);
    if (!u) return;
    this.setTransform(fitRect(u, this.viewSize()));
  }

  loadState(state: DiagramState): void {
    this.state = state;
    this.selectObjects([]);
    this.recomputeRoutes();
    this.render();
  }

  // ---- geometry helpers ---------------------------------------------------

  private viewSize(): { w: number; h: number } {
    const r = this.svg.getBoundingClientRect();
    return { w: r.width || 800, h: r.height || 600 };
  }

  private screenOf(e: { clientX: number; clientY: number }): Point {
    const r = this.svg.getBoundingClientRect();
    return { x: e.clientX - r.left, y: e.clientY - r.top };
  }

  private toCanvas(e: { clientX: number; clientY: number }): Point {
    return invert(this.t, this.screenOf(e));
  }

  private centerOfView(): Point {
    const { w, h } = this.viewSize();
    return invert(this.t, { x: w / 2, y: h / 2 });
  }

  private setTransform(t: Transform): void {
    this.t = t;
    this.renderer.setWorldTransform(t);
    this.emit();
  }

  private recomputeRoutes(): void {
    this.routes.clear();
    for (const link of this.state.links) {
      const from = this.state.objects.find((o) => o.id === link.from);
      const to = this.state.objects.find((o) => o.id === link.to);
      if (!from || !to) continue;
      const obstacles = this.state.objects.filter(
        (o) => o.id !== from.id && o.id !== to.id,
      );
      this.routes.set(link.id, routeOrtho({ from, to, obstacles }));
    }
  }

  private sceneLinks(): SceneLink[] {
    return this.state.links.flatMap((l) => {
      const points = this.routes.get(l.id);
      return points ? [{ id: l.id, points, label: l.label, dashed: l.dashed }] : [];
    });
  }

  // ---- render + notify ----------------------------------------------------

  private render(): void {
    const scene: Scene = {
      objects: this.state.objects.map((o) => ({
        id: o.id,
        kind: o.kind,
        x: o.x,
        y: o.y,
        w: o.w,
        h: o.h,
        name: o.name,
        dashed: o.dashed,
      })),
      links: this.sceneLinks(),
    };
    this.renderer.render(scene);
    this.renderer.setSelection([...this.selObjects], [...this.selLinks]);
    if (this.mode.t === 'idle') this.paintIdleOverlay();
    this.emit();
  }

  private emit(): void {
    this.onState?.(this.snapshot);
  }

  private paintIdleOverlay(): void {
    clearOverlay(this.renderer.overlay);
    if (this.selObjects.size === 1) {
      const obj = this.selectedObject();
      if (obj) {
        drawHalos(this.renderer.overlay, obj, obj.id);
        if (RESIZE_KINDS.has(obj.kind)) drawResizeHandle(this.renderer.overlay, obj, obj.id);
      }
    }
  }

  private selectObjects(ids: string[]): void {
    this.selObjects = new Set(ids);
    this.selLinks.clear();
  }

  // ---- input wiring -------------------------------------------------------

  private attach(): void {
    const svg = this.svg;
    const on = <K extends keyof SVGElementEventMap>(
      target: EventTarget,
      type: K | string,
      fn: (e: SVGElementEventMap[K] | Event) => void,
      opts?: AddEventListenerOptions,
    ) => {
      target.addEventListener(type as string, fn as EventListener, opts);
      this.detach.push(() => target.removeEventListener(type as string, fn as EventListener));
    };

    on(svg, 'pointerdown', (e) => this.onPointerDown(e as PointerEvent));
    on(window, 'pointermove', (e) => this.onPointerMove(e as PointerEvent));
    on(window, 'pointerup', (e) => this.onPointerUp(e as PointerEvent));
    on(svg, 'wheel', (e) => this.onWheel(e as WheelEvent), { passive: false });
    on(svg, 'dblclick', (e) => this.onDblClick(e as MouseEvent));
    on(window, 'keydown', (e) => this.onKeyDown(e as KeyboardEvent));
    on(window, 'keyup', (e) => {
      if ((e as KeyboardEvent).key === ' ') this.spaceDown = false;
    });
  }

  private onWheel(e: WheelEvent): void {
    e.preventDefault();
    const g = wheelGesture(e);
    if (g.kind === 'zoom') {
      this.setTransform(zoomAt(this.t, this.screenOf(e), g.factor));
    } else {
      this.setTransform(panBy(this.t, g.delta.dx, g.delta.dy));
    }
  }

  private onDblClick(e: MouseEvent): void {
    const p = this.toCanvas(e);
    const hit = pick(this.state.objects, this.sceneLinks(), p);
    if (hit?.type === 'object') this.onRenameRequest?.(hit.id);
  }

  private onKeyDown(e: KeyboardEvent): void {
    const target = e.target as HTMLElement | null;
    if (target && /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName)) return;
    if (e.key === ' ') {
      this.spaceDown = true;
      return;
    }
    const mod = e.metaKey || e.ctrlKey;
    if (mod && e.key.toLowerCase() === 'z') {
      e.preventDefault();
      if (e.shiftKey) this.undo.redo();
      else this.undo.undo();
      this.recomputeRoutes();
      this.render();
      return;
    }
    if (mod && e.key.toLowerCase() === 'y') {
      e.preventDefault();
      this.undo.redo();
      this.recomputeRoutes();
      this.render();
      return;
    }
    const digits = e.key.match(/^[1-9]$/);
    if (digits && !mod) {
      this.quickAdd(Number(e.key));
      return;
    }
    const action = actionFor(e.key, mod);
    if (!action) return;
    e.preventDefault();
    this.runAction(action);
  }

  private runAction(action: string): void {
    const { w, h } = this.viewSize();
    const center = { x: w / 2, y: h / 2 };
    switch (action) {
      case 'pan-left':
        this.setTransform(panBy(this.t, PAN_STEP_PX, 0));
        break;
      case 'pan-right':
        this.setTransform(panBy(this.t, -PAN_STEP_PX, 0));
        break;
      case 'pan-up':
        this.setTransform(panBy(this.t, 0, PAN_STEP_PX));
        break;
      case 'pan-down':
        this.setTransform(panBy(this.t, 0, -PAN_STEP_PX));
        break;
      case 'zoom-in':
        this.setTransform(zoomAt(this.t, center, ZOOM_STEP));
        break;
      case 'zoom-out':
        this.setTransform(zoomAt(this.t, center, 1 / ZOOM_STEP));
        break;
      case 'zoom-reset':
        this.setTransform({ x: 0, y: 0, k: 1 });
        break;
      case 'fit-diagram':
        this.fitDiagram();
        break;
      case 'grid-toggle':
        this.toggleGrid();
        break;
      case 'delete':
        this.deleteSelection();
        break;
      case 'escape':
        this.mode = { t: 'idle' };
        clearOverlay(this.renderer.overlay);
        this.selectObjects([]);
        this.render();
        break;
      default:
        break;
    }
  }

  // ---- pointer mode machines ---------------------------------------------

  private onPointerDown(e: PointerEvent): void {
    if (e.button === 1 || (e.button === 0 && this.spaceDown)) {
      this.mode = { t: 'pan', startScreen: this.screenOf(e), startT: this.t };
      return;
    }
    if (e.button !== 0) return;
    const halo = haloTarget(e);
    if (halo) {
      this.mode = { t: 'link', fromId: halo.id, fromSide: halo.side };
      return;
    }
    const handle = resizeTarget(e);
    if (handle) {
      const obj = this.state.objects.find((o) => o.id === handle);
      if (obj) {
        this.mode = { t: 'resize', id: obj.id, startCanvas: this.toCanvas(e), before: rectOf(obj) };
      }
      return;
    }
    const p = this.toCanvas(e);
    const hit = pick(this.state.objects, this.sceneLinks(), p);
    if (hit?.type === 'object') {
      this.beginObjectDrag(hit.id, e, p);
      return;
    }
    if (hit?.type === 'link') {
      const additive = e.shiftKey;
      const next = additive ? new Set([...this.selLinks, hit.id]) : new Set([hit.id]);
      this.selLinks = next;
      if (!additive) this.selectObjects([]);
      this.render();
      return;
    }
    // empty canvas: rubber band
    clearOverlay(this.renderer.overlay);
    if (!e.shiftKey) this.selectObjects([]);
    this.mode = { t: 'band', startCanvas: p, additive: e.shiftKey };
    this.render();
  }

  private beginObjectDrag(id: string, e: PointerEvent, p: Point): void {
    if (e.shiftKey) {
      if (this.selObjects.has(id)) this.selObjects.delete(id);
      else this.selObjects.add(id);
      this.render();
      return;
    }
    if (!this.selObjects.has(id)) this.selectObjects([id]);
    this.render();
    const before: PositionRec[] = this.state.objects
      .filter((o) => this.selObjects.has(o.id))
      .map((o) => ({ id: o.id, x: o.x, y: o.y }));
    this.mode = { t: 'drag', startCanvas: p, before, moved: false };
  }

  private onPointerMove(e: PointerEvent): void {
    switch (this.mode.t) {
      case 'pan': {
        const s = this.screenOf(e);
        this.setTransform(panBy(this.mode.startT, s.x - this.mode.startScreen.x, s.y - this.mode.startScreen.y));
        break;
      }
      case 'drag':
        this.dragMove(e);
        break;
      case 'band':
        this.bandMove(e);
        break;
      case 'link':
        this.linkMove(e);
        break;
      case 'resize':
        this.resizeMove(e);
        break;
      default:
        break;
    }
  }

  private dragMove(e: PointerEvent): void {
    const m = this.mode;
    if (m.t !== 'drag') return;
    const p = this.toCanvas(e);
    const dx = p.x - m.startCanvas.x;
    const dy = p.y - m.startCanvas.y;
    if (!m.moved && Math.abs(dx) + Math.abs(dy) < 2) return;
    m.moved = true;
    const single = m.before.length === 1 ? this.state.objects.find((o) => o.id === m.before[0]?.id) ?? null : null;
    let guideDx = 0;
    let guideDy = 0;
    const guides = [];
    if (single) {
      const moving: Rect = { x: single.x, y: single.y, w: single.w, h: single.h };
      const baseX = m.before[0]?.x ?? single.x;
      const baseY = m.before[0]?.y ?? single.y;
      const proposed: Rect = { x: baseX + dx, y: baseY + dy, w: single.w, h: single.h };
      const others = this.state.objects.filter((o) => !this.selObjects.has(o.id));
      const g = computeGuides(proposed, others);
      guideDx = g.dx;
      guideDy = g.dy;
      guides.push(...g.guides);
    }
    clearOverlay(this.renderer.overlay);
    drawGuides(this.renderer.overlay, guides);
    const next = this.state.objects.map((o) => {
      const rec = m.before.find((b) => b.id === o.id);
      if (!rec) return o;
      const x = guideDx !== 0 || guides.length > 0 ? rec.x + dx + guideDx : snapToGrid(rec.x + dx);
      const y = guideDy !== 0 || guides.length > 0 ? rec.y + dy + guideDy : snapToGrid(rec.y + dy);
      return guides.length > 0 || guideDx !== 0 || guideDy !== 0
        ? { ...o, x: rec.x + dx + guideDx, y: rec.y + dy + guideDy }
        : { ...o, x: snapToGrid(rec.x + dx), y: snapToGrid(rec.y + dy) };
    });
    void single;
    void movingUnused();
    this.state = { ...this.state, objects: next };
    this.recomputeRoutes();
    this.render();
    void m;
  }

  private bandMove(e: PointerEvent): void {
    const m = this.mode;
    if (m.t !== 'band') return;
    const p = this.toCanvas(e);
    const band = normRect(m.startCanvas, p);
    clearOverlay(this.renderer.overlay);
    drawRubberBand(this.renderer.overlay, band);
    const ids = this.state.objects
      .filter((o) => rectsOverlap(o, band))
      .map((o) => o.id);
    const base = m.additive ? [...this.selObjects] : [];
    this.renderer.setSelection([...new Set([...base, ...ids])], [...this.selLinks]);
  }

  private linkMove(e: PointerEvent): void {
    const m = this.mode;
    if (m.t !== 'link') return;
    const from = this.state.objects.find((o) => o.id === m.fromId);
    if (!from) return;
    const anchor = portPoint(from, m.fromSide);
    const p = this.toCanvas(e);
    clearOverlay(this.renderer.overlay);
    drawGhostLink(this.renderer.overlay, anchor, p);
    const hit = pick(this.state.objects.filter((o) => o.id !== m.fromId), [], p);
    const overlay = this.renderer.overlay;
    for (const o of this.state.objects) {
      const g = this.renderer.elementFor(o.id);
      g?.classList.toggle('pc-link-target', hit?.type === 'object' && hit.id === o.id);
    }
    void overlay;
  }

  private resizeMove(e: PointerEvent): void {
    const m = this.mode;
    if (m.t !== 'resize') return;
    const p = this.toCanvas(e);
    const before = m.before;
    const snapped = snapResize({
      x: before.x,
      y: before.y,
      w: Math.max(GRID_SIZE, p.x - before.x),
      h: Math.max(GRID_SIZE, p.y - before.y),
    });
    this.state = {
      ...this.state,
      objects: this.state.objects.map((o) =>
        o.id === m.id ? { ...o, x: snapped.x, y: snapped.y, w: snapped.w, h: snapped.h } : o,
      ),
    };
    clearOverlay(this.renderer.overlay);
    drawResizeHandle(this.renderer.overlay, snapped, m.id);
    this.recomputeRoutes();
    this.render();
  }

  private onPointerUp(e: PointerEvent): void {
    switch (this.mode.t) {
      case 'drag':
        this.commitDrag();
        break;
      case 'band':
        this.commitBand(e);
        break;
      case 'link':
        this.commitLink(e);
        break;
      case 'resize':
        this.commitResize();
        break;
      default:
        break;
    }
    this.mode = { t: 'idle' };
    for (const o of this.state.objects) {
      this.renderer.elementFor(o.id)?.classList.remove('pc-link-target');
    }
    this.render();
  }

  private commitDrag(): void {
    const m = this.mode;
    if (m.t !== 'drag' || !m.moved) return;
    const after: PositionRec[] = this.state.objects
      .filter((o) => m.before.some((b) => b.id === o.id))
      .map((o) => ({ id: o.id, x: o.x, y: o.y }));
    const key = m.before.length === 1 ? `pos:${m.before[0]?.id}` : `pos:multi`;
    const set = (recs: PositionRec[]) => {
      this.state = {
        ...this.state,
        objects: this.state.objects.map((o) => {
          const r = recs.find((c) => c.id === o.id);
          return r ? { ...o, x: r.x, y: r.y } : o;
        }),
      };
      this.recomputeRoutes();
      this.render();
    };
    const eq = (a: PositionRec[], b: PositionRec[]) => listEq(a, b);
    const beforeRecs = m.before.slice();
    this.undo.push({
      label: 'move',
      coalesceKey: key,
      undo: () => set(beforeRecs),
      redo: () => set(after),
      coalesce: (next: CoalescableCommand) => null,
    });
    void eq;
  }

  private commitBand(e: PointerEvent): void {
    const m = this.mode;
    if (m.t !== 'band') return;
    const band = normRect(m.startCanvas, this.toCanvas(e));
    const tiny = band.w < 2 && band.h < 2;
    const ids = tiny
      ? []
      : this.state.objects.filter((o) => rectsOverlap(o, band)).map((o) => o.id);
    const merged = m.additive ? new Set([...this.selObjects, ...ids]) : new Set(ids);
    this.selectObjects([...merged]);
  }

  private commitLink(e: PointerEvent): void {
    const m = this.mode;
    if (m.t !== 'link') return;
    const p = this.toCanvas(e);
    const hit = pick(
      this.state.objects.filter((o) => o.id !== m.fromId),
      [],
      p,
    );
    if (hit?.type !== 'object') return;
    const id = `l${++this.seq}`;
    const link: DiagramLink = { id, from: m.fromId, to: hit.id, type: 'uses' };
    this.state = { ...this.state, links: [...this.state.links, link] };
    this.recomputeRoutes();
    const before = this.state.links.filter((l) => l.id !== id);
    this.undo.push(makeLinkCommand(link, before, this));
  }

  private commitResize(): void {
    const m = this.mode;
    if (m.t !== 'resize') return;
    const obj = this.state.objects.find((o) => o.id === m.id);
    if (!obj) return;
    const before = this.state.objects;
    const after = before.map((o) => (o.id === m.id ? { ...o, x: obj.x, y: obj.y, w: obj.w, h: obj.h } : o));
    void before;
    void after;
  }
}

// ---- module helpers (DOM-free where possible) ------------------------------

function rectOf(o: Rect): Rect {
  return { x: o.x, y: o.y, w: o.w, h: o.h };
}

function normRect(a: Point, b: Point): Rect {
  return {
    x: Math.min(a.x, b.x),
    y: Math.min(a.y, b.y),
    w: Math.abs(a.x - b.x),
    h: Math.abs(a.y - b.y),
  };
}

function rectsOverlap(a: Rect, b: Rect): boolean {
  return a.x <= b.x + b.w && a.x + a.w >= b.x && a.y <= b.y + b.h && a.y + a.h >= b.y;
}

function listEq<T>(a: T[], b: T[]): boolean {
  return a.length === b.length && a.every((v, i) => v === b[i]);
}

function labelFor(kind: Kind): string {
  return kind
    .split('_')
    .map((s) => s.charAt(0).toUpperCase() + s.slice(1))
    .join(' ');
}

function haloTarget(e: Event): { id: string; side: HaloSide } | null {
  const el = (e.target as Element | null)?.closest('.pc-halo');
  if (!el) return null;
  const id = el.getAttribute('data-id');
  const side = el.getAttribute('data-side') as HaloSide | null;
  return id && side ? { id, side } : null;
}

function resizeTarget(e: Event): string | null {
  return (e.target as Element | null)?.closest('.pc-resize-handle')?.getAttribute('data-id') ?? null;
}

function movingUnused(): void {
  /* placeholder removed in cleanup */
}

interface AddRemoveCommand extends CoalescableCommand {}

function makeAddCommand(
  obj: DiagramObject,
  beforeObjects: DiagramObject[],
  ctrl: { state: DiagramState },
  linksFn: () => DiagramLink[],
): CoalescableCommand {
  void obj;
  void beforeObjects;
  void ctrl;
  void linksFn;
  throw new Error('unused');
}

function makeDeleteCommand(
  b: DiagramObject[],
  bl: DiagramLink[],
  a: DiagramObject[],
  al: DiagramLink[],
  ctrl: CanvasController,
): CoalescableCommand {
  void b;
  void bl;
  void a;
  void al;
  void ctrl;
  throw new Error('unused');
}

function makeLinkCommand(
  link: DiagramLink,
  before: DiagramLink[],
  ctrl: CanvasController,
): CoalescableCommand {
  void link;
  void before;
  void ctrl;
  throw new Error('unused');
}
