      return;
    }
    if (!e.shiftKey) this.selectObjects([]);
    this.mode = { t: 'band', startCanvas: p, additive: e.shiftKey };
    this.render();
  }

  private beginObjectDrag(id: string, e: PointerEvent, p: Point): void {
    if (e.shiftKey) {
