      .filter((o) => this.selObjects.has(o.id))
      .map((o) => ({ id: o.id, x: o.x, y: o.y }));
    this.mode = { t: 'drag', startCanvas: p, before, moved: false };
  }

  private onPointerMove(e: PointerEvent): void {
    switch (this.mode.t) {
      case 'pan': {
        const s = this.screenOf(e);
