    return act(async () => {}).then(() => {
      const tags2 = screen.getByTestId('prop-tags') as HTMLInputElement;
      console.log('after flush: tags.value =', JSON.stringify(tags2.value));
      expect(tags2.value).toBe('');
    });
  });
});
